&lt;li&gt;&lt;a href=&quot;#_la_solution_créer_le_symlink_current_pour_nvm&quot;&gt;La solution : créer le symlink &lt;code&gt;current&lt;/code&gt; pour NVM&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_automatiser_la_mise_à_jour_du_symlink&quot;&gt;Automatiser la mise à jour du symlink&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
