@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;लाभ&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;विवरण&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;sudo नहीं&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;IDE के सभी फ़ाइल उपयोगकर्ता के हैं।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;CSS का सीधा संशोधन&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;पैच किया जा सकता है`workbench.desktop.main.css`विशेषाधिकार वृद्धि के बिना&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;घरेलू अपडेट स्क्रिप्ट&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;एक साधारण शेल स्क्रिप्ट स्वचालित रूप से डाउनलोड, प्रतिस्थापित और पुनः पैच करती है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अलगाव&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सिस्टम इंस्टॉलेशन प्रदूषित नहीं है ; rollback = फ़ोल्डर हटाएँ&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_मुख्य_मेनू_के_फ़ॉन्ट_को_अनुकूलित_करें&quot;&gt;मुख्य मेनू के फ़ॉन्ट को अनुकूलित करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निरीक्षण&quot;&gt;निरीक्षण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मुख्य मेनू (फ़ाइल, संपादन, दृश्य &amp;#8230;&amp;#8203;) और ड्रॉप‑डाउन का डिफ़ॉल्ट फ़ॉन्ट बहुत छोटा है। VS Code में इसे बदलने के लिए कोई सेटिंग नहीं है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_तकनीक_सीधा_सीएसएस_पैच&quot;&gt;तकनीक : सीधा सीएसएस पैच&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ाइल के अंत में CSS जोड़ें`workbench.desktop.main.css`(No output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 6) ]

@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor Développeur as dev
participant &quot;workbench.desktop
^^^^^
 Syntax Error? (Assumed diagram type: sequence)

@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor Développeur as dev
participant &quot;workbench.desktop
.main.css&quot; as css
participant &quot;product.json&quot; as product
participant &quot;VS कोड&quot; as vscode

== Patch CSS ==
dev -&amp;gt; css : Ajouter règles font-size\n(.menubar-menu-title, etc.)
dev -&amp;gt; vscode : Redémarrer VS Code
vscode -&amp;gt; vscode : Charge le CSS patché
vscode --&amp;gt; dev : Menus et dropdowns en 23px/22px ✓

== Suppression warning ==
vscode --&amp;gt; dev : ⚠️ &quot;आपकी स्थापना दूषित है&quot;
dev -&amp;gt; product : Supprimer clé &quot;चेकसम&quot;\n(python3 -c ...)
dev -&amp;gt; vscode : Redémarrer VS Code
vscode --&amp;gt; dev : Plus de warning ✓

note over css, product
  Deux fichiers dans ~/apps/
  = modifiables sans sudo
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;CSS_FILE=&quot;$HOME/apps/VSCode-linux-x64/resources/app/out/vs/workbench/workbench.desktop.main.css&quot;

cat &amp;gt;&amp;gt; &quot;$CSS_FILE&quot; &amp;lt;&amp;lt; &#39;EOF&#39;
.menubar-menu-title{font-size:23px!important}
.menubar&amp;gt;.menubar-menu-button{font-size:23px!important}
.monaco-menu-option{font-size:22px!important;line-height:34px!important}
.monaco-menu .action-label:not(.codicon){font-size:22px!important}
.menubar-menu-items-holder .monaco-menu .action-item .action-label{font-size:22px!important}
EOF&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सत्यनिष्ठा_चेतावनी_हटाएँ&quot;&gt;सत्यनिष्ठा चेतावनी हटाएँ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code अपने फ़ाइलों में हुए परिवर्तनों का पता लगाता है और एक बैनर प्रदर्शित करता है &quot;Your installation is corrupt&quot;। इससे बचने के लिए, हम चेकसम हटा देते हैं`product.json`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-python hljs&quot; data-lang=&quot;python&quot;&gt;import json
product_json = &quot;$HOME/apps/VSCode-linux-x64/resources/app/product.json&quot;
with open(product_json, &#39;r&#39;) as f:
    data = json.load(f)
data.pop(&#39;checksums&#39;, None)
with open(product_json, &#39;w&#39;) as f:
    json.dump(data, f, indent=2)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;रीस्टार्ट के बाद, कोई चेतावनी नहीं रहती और मेनू अंततः पढ़ने योग्य हो जाते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एक्सप्लोरर_पैनल_का_फ़ॉन्ट_कस्टमाइज़_करें_लड़ाई&quot;&gt;एक्सप्लोरर पैनल का फ़ॉन्ट कस्टमाइज़ करें — लड़ाई&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_टेंटेटिव1_ऐसा_पैरामीटर_जो_नहीं_मौजूद_है&quot;&gt;टेंटेटिव 1: ऐसा पैरामीटर जो नहीं मौजूद है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहले हम स्वाभाविक पैरामीटर का प्रयास करते हैं`workbench.tree.fontSize`में`settings.json`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
    &quot;workbench.tree.fontSize&quot;: 20
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;कोई प्रभाव नहीं&lt;/strong&gt;. यह सेटिंग VS Code में मौजूद नहीं है। इसका सबूत यह है कि अनमान्य सेटिंग्स चुपचाप अनदेखी कर दिए जाते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रयास_2_एक्सटेंशन_custom_css_and_js_loader&quot;&gt;प्रयास 2 : एक्सटेंशन Custom CSS and JS Loader&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम एक्सटेंशन इंस्टॉल करते हैं`be5invis.vscode-custom-css`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;~/apps/VSCode-linux-x64/bin/code --install-extension be5invis.vscode-custom-css&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम एक CSS फ़ाइल बनाते हैं`~/.vscode-custom-css/custom.css`एक्सप्लोरर के तत्वों को लक्षित करने वाले चयनकर्ताओं के साथ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.monaco-tree-rows .monaco-tree-row,
.sidebar .monaco-list-row,
.explorer-viewlet .monaco-list-row,
.monaco-list-row .monaco-icon-label {
    font-size: 22px !important;
    line-height: 36px !important;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और हम इस फ़ाइल को सेटिंग्स में संदर्भित करते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
    &quot;vscode_custom_css.imports&quot;: [
        &quot;file:///home/user/.vscode-custom-css/custom.css&quot;
    ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;परिवर्तन लागू नहीं होते.&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_जाल_हर_बार_एक्सटेंशन_को_सक्रिय_करना_होगा&quot;&gt;जाल: हर बार एक्सटेंशन को सक्रिय करना होगा&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक्सटेंशन की दस्तावेज़ीकरण इस महत्वपूर्ण बिंदु पर चुप है: प्रत्येक कस्टम CSS संशोधन के बाद, आपको यह करना होगा&lt;strong&gt;अनिवार्य रूप से&lt;/strong&gt;कमांड चलाएँ पैलेट से :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;→ टाइप करना&lt;strong&gt;कस्टम CSS और JS सक्षम करें&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;VS Code को रीस्टार्ट की आवश्यकता है → स्वीकार करें&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस चरण के बिना, सीएसएस कभी भी IDE में इंजेक्ट नहीं किया जाता।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रयास_3_रेखाएँ_ओवरलैप_होती_हैं&quot;&gt;प्रयास 3: रेखाएँ ओवरलैप होती हैं&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;के साथ भी`font-size: 22px` et &lt;code&gt;line-height: 36px&lt;/code&gt;, जैमबेज वाले अक्षर (g, p, f, b) पड़ोस वाली लाइनों पर फैल जाते हैं. हम जोड़ने की कोशिश कर रहे हैं`height` et &lt;code&gt;min-height&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.monaco-list-row {
    height: 36px !important;
    min-height: 36px !important;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;कोई बदलाव नहीं&lt;/strong&gt;. VS Code JavaScript में लाइनों की ऊँचाइयाँ गणना करता है और CSS मानों को ओवरराइड करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_zoom_मातृ_कंटेनर_पर&quot;&gt;समाधान : &lt;code&gt;zoom&lt;/code&gt; मातृ कंटेनर पर&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 5) ]

@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;प्रयास 1
पैरामीटर मौजूद नहीं है&quot; #LightCoral {
