&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;पहुँच&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;CSS&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;परिणाम&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;font-size`पर&lt;/code&gt;.monaco-list-row`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;font-size: 22px !important&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बड़ा पाठ लेकिन रेखाएँ अ overlap&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
