&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_आर्किटेक्चरल_विज़न&quot;&gt;आर्किटेक्चरल विज़न&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निर्देशक_सिद्धांत&quot;&gt;निर्देशक सिद्धांत&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आर्किटेक्चर &lt;strong&gt;विचारों के पृथक्करण&lt;/strong&gt; के सिद्धांत पर आधारित है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;sagri&lt;/strong&gt; : एससीआईडॉक्स फ़ाइलें संरचित मेटाडेटा के साथ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;प्रस्तुति&lt;/strong&gt; : templates Thymeleaf पुन: उपयोग करने योग्य&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;डेटा&quot; : JBake द्वारा AsciiDoc属性 से स्वचालित रूप से निकाला गया मॉडल&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;शैली&lt;/strong&gt; : Bootstrap 5 को दृश्यात्मक सुसंगतता के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_रणनीतिक_विकल्प_पोर्टफोलियो_के_लिए_asciidoc&quot;&gt;रणनीतिक विकल्प: पोर्टफोलियो के लिए AsciiDoc&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्यों AsciiDoc ?&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;मापदंड&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;लाभ&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;संगति&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Même format que les articles de blog&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;मेटाडेटा&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;संरचित और विस्तारयोग्य गुण (&lt;code&gt;project-*&lt;/code&gt;)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;रखरखावयोग्यता&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सरल टेक्स्ट संपादन, Git-संस्करणीय&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;लचीलापन&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;इसमें समृद्ध सामग्री (तालिकाएँ, कोड, छवियाँ) हो सकती है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;टेम्प्लेटिंग&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;JBake स्वचालित रूप से Thymeleaf के लिए अट्रिब्यूट निकालता है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_डेटा_मॉडल&quot;&gt;डेटा मॉडल&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हर पोर्टफ़ोलियो प्रोजेक्ट एक AsciiDoc दस्तावेज़ है, जिसके साथ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;शीर्षक मेटाडेटा&lt;/strong&gt; : संरचित जानकारी (ग्राहक, अवधि, प्रौद्योगिकियाँ, आदि)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;दस्तावेज़ का शरीर&lt;/strong&gt; : कथात्मक विवरण, चुनौतियाँ, समाधान, परिणाम&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;वैयक्तिकृत विशेषताएँ: पूर्वसंयोजित`project-*`स्वचालित निष्कर्षण के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
