&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;migration-strategy.svg&quot; alt=&quot;migration strategy&quot; width=&quot;2050&quot; height=&quot;954&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_लागत_और_परिचालन_विचार&quot;&gt;लागत और परिचालन विचार&lt;/h2&gt;
