&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_gradle_निर्भरताएँ&quot;&gt;Gradle निर्भरताएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_logback_कॉन्फ़िगरेशन&quot;&gt;Logback कॉन्फ़िगरेशन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पूरी_परीक्षा_वर्ग&quot;&gt;पूरी परीक्षा वर्ग&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_बहु_स्तरीय_लॉगिंग_स्कीमा&quot;&gt;बहु-स्तरीय लॉगिंग स्कीमा&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सर्वोत्तम_प्रथाएँ&quot;&gt;सर्वोत्तम प्रथाएँ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_अनुशंसित_लॉगिंग_संरचना&quot;&gt;अनुशंसित लॉगिंग संरचना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_दृश्य_प्रतीक_पठनीयता_के_लिए&quot;&gt;दृश्य प्रतीक पठनीयता के लिए&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_आउटपुट_से_सूचना_निष्कर्षण&quot;&gt;आउटपुट से सूचना निष्कर्षण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_तुलना_पहलेबाद&quot;&gt;तुलना पहले/बाद&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_पहले_समस्यात्मक_पद्धति&quot;&gt;पहले: समस्यात्मक पद्धति&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_बाद_मzboused_दृष्टिकोण&quot;&gt;बाद : मzboused दृष्टिकोण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
