&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पाइपलाइन_की_वस्तुएँ_और_मॉडल&quot;&gt;पाइपलाइन की वस्तुएँ और मॉडल&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_क्लास_आरेख_cicd_मॉडल&quot;&gt;क्लास आरेख - CI/CD मॉडल&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/diag-plantuml-md5-b297b21c69498b5bc74f0da88d80315f.png&quot; alt=&quot;Diagram&quot; width=&quot;814&quot; height=&quot;635&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सिक्रेट्स_की_कॉन्फ़िगरेशन&quot;&gt;सिक्रेट्स की कॉन्फ़िगरेशन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पाइपलाइन काम करने के लिए, आपको GitHub में निम्नलिखित सीक्रेट्स कॉन्फ़िगर करने होंगे :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_github_actions_के_रहस्य&quot;&gt;GitHub Actions के रहस्य&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;bash&quot;&gt;# Dans Settings &amp;gt; Secrets and variables &amp;gt; Actions

# Token PyPI pour la production
PYPI_API_TOKEN=pypi-...

# Token Test PyPI pour les pré-releases
TEST_PYPI_API_TOKEN=pypi-...

# Token GitHub pour créer les releases
GITHUB_TOKEN=(automatiquement fourni)

# Token Codecov (optionnel)
CODECOV_TOKEN=...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pypi_टोकन_जनरेशन&quot;&gt;PyPI टोकन जनरेशन&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;bash&quot;&gt;# 1. Créer un compte sur PyPI et Test PyPI
# 2. Aller dans Account Settings &amp;gt; API tokens
# 3. Créer un token avec scope &quot;Entire account&quot; ou spécifique au projet
# 4. Format du token : pypi-AgEIcHlwaS5vcmc...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_स्थानीय_विकास_स्क्रिप्ट&quot;&gt;स्थानीय विकास स्क्रिप्ट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;विकास को आसान बनाने के लिए, उपयोगिता स्क्रिप्ट बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_makefile&quot;&gt;Makefile&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;makefile&quot;&gt;.PHONY: install test lint format security build clean release-test release-prod

install:
	pip install -e &quot;.[dev]&quot;

test:
	pytest tests/ -v --cov=src/playlist_downloader

lint:
	flake8 src tests
	mypy src

format:
	black src tests

security:
	bandit -r src/
	safety check

build:
	python -m build
	twine check dist/*

clean:
	rm -rf build/ dist/ *.egg-info/
	find . -type d -name __pycache__ -delete
	find . -name &quot;*.pyc&quot; -delete

release-test: clean build
	twine upload --repository testpypi dist/*

release-prod: clean build
	twine upload dist/*

pre-commit: format lint test security
	@echo &quot;✅ Prêt pour commit&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्क्रिप्ट_संस्करण&quot;&gt;स्क्रिप्ट संस्करण&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;python&quot;&gt;#!/usr/bin/env python3
&quot;&quot;&quot;Script pour gérer les versions du projet.&quot;&quot;&quot;

import sys
import subprocess
from pathlib import Path

def get_current_version():
    &quot;&quot;&quot;Récupère la version actuelle depuis git.&quot;&quot;&quot;
    try:
        result = subprocess.run(
            [&quot;git&quot;, &quot;describe&quot;, &quot;--tags&quot;, &quot;--abbrev=0&quot;],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError:
        return &quot;0.0.0&quot;

def create_version_tag(version, message=None):
    &quot;&quot;&quot;Crée un tag de version.&quot;&quot;&quot;
    if not version.startswith(&#39;v&#39;):
        version = f&#39;v{version}&#39;

    tag_message = message or f&quot;Release {version}&quot;

    subprocess.run([&quot;git&quot;, &quot;tag&quot;, &quot;-a&quot;, version, &quot;-m&quot;, tag_message], check=True)
    print(f&quot;✅ Tag {version} créé&quot;)

    # Push le tag
    subprocess.run([&quot;git&quot;, &quot;push&quot;, &quot;origin&quot;, version], check=True)
    print(f&quot;✅ Tag {version} poussé vers origin&quot;)

if __name__ == &quot;__main__&quot;:
    if len(sys.argv) &amp;lt; 2:
        current = get_current_version()
        print(f&quot;Version actuelle: {current}&quot;)
        print(&quot;Usage: python version.py &amp;lt;new_version&amp;gt; [message]&quot;)
        sys.exit(1)

    new_version = sys.argv[1]
    message = sys.argv[2] if len(sys.argv) &amp;gt; 2 else None

    create_version_tag(new_version, message)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अच्छी_प्रथाएँ_और_सिफारिशें&quot;&gt;अच्छी प्रथाएँ और सिफारिशें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समानार्थिक_संस्करण&quot;&gt;समानार्थिक संस्करण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सेमेंटिक वर्जनिंग (SemVer) का उपयोग करें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR.MINOR.PATCH&lt;/code&gt; (ex: 1.2.3)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR&lt;/code&gt;: असंगत परिवर्तन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MINOR&lt;/code&gt;: नए संगत विशेषताएँ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`PATCH`संगत बग सुधार&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ब्रांचिंग_रणनीति&quot;&gt;ब्रांचिंग रणनीति&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;text&quot;&gt;main          ──●──●──●──●──●────●── (releases stables)
               /       /          /
develop    ──●──●──●──●──●──●──●──●── (développement)
            /     /        /
feature/xxx  ●──●──●──●──●──/ (fonctionnalités)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_टेस्ट_और_कवरेज&quot;&gt;टेस्ट और कवरेज&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;कोड कवरेज न्यूनतम : 85%&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;यूनिट टेस्ट व्यावसायिक तर्क के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;एडेप्टर्स के लिए एकीकरण परीक्षण&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;CLI के लिए एंड-टू-एंड परीक्षण&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सुरक्षा&quot;&gt;सुरक्षा&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;निर्भरताओं का स्वचालित स्कैन (Safety)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कोड का स्थैतिक विश्लेषण (Bandit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कोड में कभी भी रहस्य नहीं&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;विशिष्ट PyPI टोकन का उपयोग&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_मॉनिटरिंग_और_ऑब्ज़र्वेबिलिटी&quot;&gt;मॉनिटरिंग और ऑब्ज़र्वेबिलिटी&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_पाइपलाइन_मेट्रिक्स&quot;&gt;पाइपलाइन मेट्रिक्स&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;# .github/workflows/metrics.yml
name: Pipeline Metrics

on:
  workflow_run:
    workflows: [&quot;CI&quot;, &quot;Release&quot;]
    types: [completed]

jobs:
  metrics:
    runs-on: ubuntu-latest
    steps:
    - name: Collect metrics
      run: |
        echo &quot;Pipeline: ${{ github.event.workflow_run.name }}&quot;
        echo &quot;Status: ${{ github.event.workflow_run.conclusion }}&quot;
        echo &quot;Duration: ${{ github.event.workflow_run.updated_at - github.event.workflow_run.created_at }}&quot;
        # Envoyer vers système de monitoring&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सूचनाएँ&quot;&gt;सूचनाएँ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;# Ajout dans les workflows pour notifications
- name: Notify on failure
  if: failure()
  uses: 8398a7/action-slack@v3
  with:
    status: failure
    text: &quot;❌ Pipeline failed for ${{ github.repository }}&quot;
  env:
    SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK }}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह पायथन के लिए पूर्ण CI/CD पाइपलाइन प्रदान करता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;पूर्ण स्वचालन&lt;/strong&gt;: कोड की सत्यापन से प्रकाशन तक&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;सुरक्षा&lt;/strong&gt;स्वचालित स्कैन और सुरक्षित रहस्य प्रबंधन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गुणवत्ता&lt;/strong&gt;: बहु- संस्करणों के परीक्षण, लिंटिंग और कोड कवरेज&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;विश्वसनीयता&lt;/strong&gt;: Test PyPI के माध्यम से क्रमिक तैनाती&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ट्रेसेबिलिटी&lt;/strong&gt;: artifacts, रिपोर्ट और releases GitHub&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इन प्रथाओं को अपनाने से आपके Python CLI एप्लिकेशनों के लिए एक मजबूत और पेशेवर डिलीवरी प्रक्रिया सुनिश्चित होती है, जिससे आपके प्रोजेक्ट्स की रखरखाव और दीर्घकालिक विकास आसान हो जाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अतिरिक्त_संसाधन&quot;&gt;अतिरिक्त संसाधन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://packaging.python.org/&quot;&gt;Python Packaging User Guide&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.github.com/en/actions&quot;&gt;GitHub Actions दस्तावेज़&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://pypi.org/help/&quot;&gt;PyPI मदद दस्तावेज़&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://semver.org/&quot;&gt;सेमेंटिक वर्ज़निंग विनिर्देश&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://keepachangelog.com/&quot;&gt;चेंजलॉग रखें&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संदर्भ_और_वर्तमान_चुनौतियाँ&quot;&gt;संदर्भ और वर्तमान चुनौतियाँ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_संगीत_apis_का_विकास&quot;&gt;संगीत APIs का विकास&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लॉग_चालित_विकास_की_पद्धति&quot;&gt;लॉग-चालित विकास की पद्धति&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सैद्धांतिक_वास्तुकला&quot;&gt;सैद्धांतिक वास्तुकला&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_स्टैक_तकनीक_और_फ़ंक्शनल_पैराडाइम&quot;&gt;स्टैक तकनीक और फ़ंक्शनल पैराडाइम&lt;/a&gt;
