&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_abstract_class_reportfunctionalteststask_opentestreporttask_init_description_फ़ायरफ़ॉक्स_में_फंक्शनल_टेस्ट_रिपोर्ट_खोलता_है_reportpath_buildreportstestsfunctionaltestindex_html&quot;&gt;abstract class ReportFunctionalTestsTask : OpenTestReportTask() { init { description = &quot;फ़ायरफ़ॉक्स में फंक्शनल टेस्ट रिपोर्ट खोलता है।&quot; reportPath = &quot;build/reports/tests/functionalTest/index.html&quot; } }&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;\=== कार्यों का अभिलेख&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;में`build.gradle.kts`आपके मूल प्रोजेक्ट :&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sourcekotlin&quot;&gt;[source,kotlin]&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tasks_registercom_yourpackage_reportunitteststaskreporttests_tasks_registercom_yourpackage_reportfunctionalteststaskreportfunctionaltests&quot;&gt;tasks.register\&amp;lt;com.yourpackage.ReportUnitTestsTask\&amp;gt;(&quot;reportTests&quot;) {} tasks.register\&amp;lt;com.yourpackage.ReportFunctionalTestsTask\&amp;gt;(&quot;reportFunctionalTests&quot;) {}&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_रिपोर्ट_कार्यों_का_uml_आरेख_कोड_plantuml&quot;&gt;रिपोर्ट कार्यों का UML आरेख (कोड PlantUML)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;नीचे दिया गया कोड कॉपी करें और इसे PlantUML को समर्थन करने वाले उपकरण में पेस्ट करें।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sourceplantuml_2&quot;&gt;[source,plantuml]&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;@startuml skinparam handwritten true skinparam monochrome true&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;abstract class DefaultTask { }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;abstract class Exec { \+ commandLine(args: String&amp;#8230;&amp;#8203;) \+ exec() }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;abstract class OpenTestReportTask extends DefaultTask { \+ group: String = &quot;verification \+ description: String \+ dependsOn(&quot;check&quot;) \+ abstract reportPath: String \+ openReport() : void }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अमूर्त वर्ग AbstractJbakeExecTask Exec को विस्तारित करता है { \+ group: String = &quot;verification \+ विवरण: स्ट्रिंग \+ dependsOn(&quot;check&quot;) \+ abstract reportRelativePath: String \+ exec() : void }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;class ReportUnitTestsTask extends OpenTestReportTask { \+ reportPath: String = &quot;build/reports/tests/test/index.html }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्लास ReportFunctionalTestsTask विस्तार OpenTestReportTask { \+ reportPath: String = &quot;build/reports/tests/functionalTest/index.html }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;class ReportJbakeTestsTask extends AbstractJbakeExecTask { + reportRelativePath: String = &quot;build/reports/tests/test/index.html }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;class ReportJbakeFunctionalTestsTask extends AbstractJbakeExecTask { \+ reportRelativePath: String = &quot;build/reports/tests/functionalTest/index.html }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;OpenTestReportTask &amp;lt;-- ReportUnitTestsTask OpenTestReportTask &amp;lt;-- ReportFunctionalTestsTask&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AbstractJbakeExecTask &amp;lt;-- ReportJbakeTestsTask AbstractJbakeExecTask &amp;lt;-- ReportJbakeFunctionalTestsTask&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;DefaultTask \&amp;lt;|-- OpenTestReportTask Exec \&amp;lt;|-- AbstractJbakeExecTask &lt;mark&gt;#&lt;/mark&gt; ग्रेडल एकीकरण JBake को JBake ग्रेडल प्लगइन का उपयोग करके या JBake सीएलआई को सीधे बुलाकर ग्रेडल बिल्ड में एकीकृत किया जा सकता है: ```kotlin tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) { mainClass.set(&quot;org.jbake.launcher.Main&quot;) classpath = configurations[&quot;jbake&quot;] args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;) }&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_enduml&quot;&gt;@enduml&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अमूर्त कार्य`AbstractJbakeExecTask`(विरासत प्राप्त`Exec`)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यदि आपका कार्य मुख्य रूप से परिवर्तनीय तर्कों के साथ एक बाहरी कमांड निष्पादित करने तक सीमित है, तो सीधे से विरासत में लेना**&lt;mark&gt;#&lt;/mark&gt; ग्रेडल एकीकरण JBake को Gradle बिल्ड में JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर एकीकृत किया जा सकता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}**यह अधिक सीधा है।

## [source,kotlin]

package com.yourpackage

import org.gradle.api.tasks.Exec import org.gradle.api.tasks.Input import java.io.File

अमूर्त वर्ग AbstractJbakeExecTask : Exec() {

----

init { group = &quot;verification&quot; description = &quot;Opens a Jbake project report in Firefox.&quot; dependsOn(&quot;check&quot;) }

@get:Input abstract var reportRelativePath: String

override fun exec() { val separator = File.separator val reportFile = project.layout.projectDirectory.asFile.toPath() .resolve(reportRelativePath.replace(&quot;/&quot;, separator)) .toAbsolutePath() .toFile()

if (!reportFile.exists()) { logger.warn(&quot;Report file does not exist: $reportFile. Ensure &#39;check&#39; ran.&quot;) return }

commandLine(&quot;firefox&quot;, &quot;--new-tab&quot;, reportFile.absolutePath) logger.lifecycle(&quot;Attempting to open report: ${reportFile.absolutePath}&quot;) super.exec() // Appelle la méthode exec() de la super-classe Exec }

## }

\=== ठोस कार्यान्वयन के लिए`Exec`

