&lt;li&gt;&lt;a href=&quot;#_सहायता_दिखाएँ&quot;&gt;सहायता दिखाएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jvm_का_सिस्टम_प्रॉपर्टी_सेट_करें_d_system_prop&quot;&gt;JVM का सिस्टम प्रॉपर्टी सेट करें : `-D, --system-prop&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_परियोजना_की_संपत्ति_को_बिल्ड_स्क्रिप्ट_के_लिए_परिभाषित_करें_pmypropmyvalue&quot;&gt;परियोजना की संपत्ति को बिल्ड स्क्रिप्ट के लिए परिभाषित करें : `-Pmyprop=myvalue&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_gradle_की_स्टार्टअप_निर्देशिका_निर्दिष्ट_करता_है_डिफ़ॉल्ट_मान_वर्तमान_निर्देशिका_है&quot;&gt;Gradle की स्टार्टअप निर्देशिका निर्दिष्ट करता है। डिफ़ॉल्ट मान वर्तमान निर्देशिका है।&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कमांड_लाइन_से_param_component_property_को_ओवरराइट_करें&quot;&gt;कमांड लाइन से &#39;param_component&#39; property को ओवरराइट करें :&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kotlin_dsl_के_साथ_एक_सामान्य_प्रोज़क्ट_में_सोर्स_सेट_में_एक_फ़ोल्डर_जोड़ें&quot;&gt;Kotlin DSL के साथ एक सामान्य प्रोज़क्ट में सोर्स-सेट में एक फ़ोल्डर जोड़ें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एंड्रॉइड_प्रोजेक्ट_में_स्रोत_सेट_में_ग्रोवी_dsl_के_माध्यम_से_फ़ोल्डर_जोड़ें&quot;&gt;एंड्रॉइड प्रोजेक्ट में स्रोत सेट में ग्रोवी DSL के माध्यम से फ़ोल्डर जोड़ें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_सब_मॉड्यूल_का_निर्माण_और_परीक्षण_करने_से_बचें&quot;&gt;एक सब मॉड्यूल का निर्माण और परीक्षण करने से बचें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tar_एक_फ़ोल्डर&quot;&gt;Tar एक फ़ोल्डर&lt;/a&gt;&lt;/li&gt;
